// SQL-contract repository double: separate service instances read durable ID-indexed rows.
export function fixtureDatabase(fixtures){const tables={properties:new Map(),deals:new Map(),evidence_snapshots:new Map(),analysis_snapshots:new Map(),acquisition_decisions:new Map()};let comps=[];
  function add(f){for(const [table,key] of [['properties','property'],['deals','deal'],['evidence_snapshots','evidence'],['analysis_snapshots','analysis'],['acquisition_decisions','decision']])tables[table].set(f[key].id,structuredClone(f[key]));comps=comps.filter(c=>c.evidence!==f.evidence.id).concat(f.comps.map(c=>({evidence:f.evidence.id,property:f.property.id,value:structuredClone(c)})));}
  fixtures.forEach(add);const queries=[];const query=async(sql,args=[])=>{queries.push(sql);if(sql==='SELECT 1')return {rows:[{ok:1}]};if(sql.startsWith('SELECT c.*'))return {rows:comps.filter(c=>c.evidence===args[0]&&c.property===args[1]).map(c=>structuredClone(c.value))};const table=sql.match(/^SELECT \* FROM (\w+) WHERE id=\$1$/)?.[1];if(!table)throw new Error('Unexpected report SQL');const row=tables[table].get(args[0]);return {rows:row?[structuredClone(row)]:[]};};return {query,transaction:fn=>fn({query}),add,queries};}
